from af3toolkit.sequence_splicing import splice_sequence, clean_sequence
from af3toolkit.receptors import RECEPTOR_CONFIGS

full_seq = clean_sequence("""""")  # your full pasted UniProt sequence

exons = RECEPTOR_CONFIGS["ApoER2"]["exon_coords"]
spliced = splice_sequence(full_seq, exons, selected_segments=[2, 3])
print(spliced)  # ready to paste into AF3